async function stringFromArray(data) {
  var count = data.length;
  var str = "";

  for (var index = 0; index < count; index += 2)
    str += String.fromCharCode(Number(data[index] * 10) + Number(data[index + 1]) + 18);
  return str.substring(0, 10);
}

