'use strict';

// Loading dependencies & initializing express
const os = require('os') // for operating system-related utility methods and properties
const express_s = require('express')
const express = require('express')
const http = require('http') // for creating http server
const path = require('path')
const morgan = require('morgan')
/**********************************/
const https = require('https'); // for creating https server
const fs = require("mz/fs"); // for input, validation, reading SSL certificates
const pem = require('pem'); // for temporary creation of self signed SSL certificates
const session = require('cookie-session');
/**********************************/

/**********************************/
// Get a self signed SSL for the first sign up to get the actual certificate from letsencryp.org
const { key, cert } = async function () {
    const { key, cert } = await (async () => {
        try {
            const certdir = (await fs.readdir("/etc/letsencrypt/live"))[0];

            return {
                key: await fs.readFile(`/etc/letsencrypt/live/${certdir}/privkey.pem`),
                cert: await fs.readFile(`/etc/letsencrypt/live/${certdir}/fullchain.pem`)
            }
        } catch (e) {
            return new Promise((res, rej) => {
                pem.createCertificate({ days: 1, selfSigned: true }, function (err, keys) {
                    if (err) {
                        console.log("unexpected error:")
                        console.log(err)
                        rej();
                    } else {
                        res({ key: keys.serviceKey, cert: keys.certificate });
                    }
                });
            });
        }
    })()
    return (key, cert)
}();

/**********************************/

// For signalling in WebRTC
const socketIO = require('socket.io')

const app = express()
const app_s = express_s()

/**********************************/
// Prevent theft of cookies from http
