  role = req.user.role;
  if (role === 'student') {
    role = 'student';
    return role;
  }
  if (role === 'admin') {
    role = 'admin';
    return role;
  }
  role = 'bidder';
  return role;
}

// Set Query based on Role Fx
function setQuery(req) {
  // eslint-disable-next-line prefer-destructuring
  let role;
  let query;
  if (req.user === null || req.user === undefined) {
    role = 'Not Found';
    return role;
  }
  // eslint-disable-next-line prefer-destructuring
  role = req.user.role;
  if (role === 'student') {
    query = { artist_email_input: findEmail(req) };
    return query;
  }
  if (role === 'admin') {
    // const query = { school: findSchoolName(req), approved: true };
    query = { school: findSchoolName(req) };
    return query;
  }
  role = 'bidder';
  query = { school: findSchoolName(req), approved: true };
  return query;
}

// Find first_name Fx
function findFirstName(req) {
  // eslint-disable-next-line prefer-destructuring
  let first_name;
  if (req.user === null || req.user === undefined) {
    first_name = 'Your';
    return first_name;
  }
  // eslint-disable-next-line prefer-destructuring
  first_name = req.user.first_name;
  return first_name;
}

// get File ext/type
function getFileType(file) {
  const splitfile = file.split('.');
  const getThisType = splitfile[splitfile.length - 1];
  return getThisType;
}
// Find Id
function findId(req) {
  let reqvar;
  if (req.user === null || req.user === undefined) {
    reqvar = 'Not Available';
    return reqvar;
  }
  // eslint-disable-next-line no-underscore-dangle
  reqvar = req.user._id;
  return reqvar;
}

