const REDIRECT_WHITELIST = ['/']

const safeRedirect = (req, res, fallback) => {
  const referer = req.headers.referer
  if (typeof referer === 'string' && referer.length > 0 && REDIRECT_WHITELIST.indexOf(referer) >= 0) {
    res.redirect(referer)
  } else {
    res.redirect(fallback)
  }
}

if (errors) {
  req.session.body = req.body
  req.session.errors = errors
  safeRedirect(req, res, '/author/create')
} else {
  req.session.body = null
  req.session.errors = null
  let author = new Author({
    firstName: req.body.firstName,
    lastName: req.body.lastName,
    createdBy: req.user
  })
  if (req.file) {
    author.image = req.file.path.split('public').pop()
  }
  author.save((err) => {
    if (err) {
      req.session.body = req.body
      req.session.errors = [{ msg: 'There is already an author with this name' }]
      safeRedirect(req, res, '/author/create')
    } else {
      req.session.body = null
      req.session.errors = null
      res.redirect('/authors')
    }
  })
}

