    router.post("/create-directory", (req, res) => {
        req.on('data', (chunk) => {
            let data = "";
            data += chunk;
            data = JSON.parse(data);
            let currentFile = "";
            currentFile = data.path ? `${data.path}/${data.name}/` : `${data.name}/`;
            const reg = new RegExp('[\\\\/:*?"<>|]');
            if (reg.test(data.name.toString())) {
                return res.send({
                    result: {
                        'status': 'danger',
                        'message': "IllegalCharacter"
                    }
                });
            }
            api.createOssDirectory(data.disk, currentFile, req.session.user).then((result) => {
                if (result === 'createErr') {
                    res.send({
                        result: {
                            'status': 'danger',
                            'message': "dirCreateFail"
                        }
                    });
                } else if (result === 'exist') {
                    res.send({
                        result: {
                            'status': 'danger',
                            'message': "dirExist"
                        }
                    });
                } else {
                    res.send({
                        result: {
                            'status': 'success',
                            'message': "dirCreated"
                        },
                        directory: result,
                        tree: [result]
                    })
                }
            });
        })
    });

    /**
     * 删除文件
     */
    router.post("/delete", (req, res) => {
        req.on("data", function (chunk) {
            let data = "";
            data += chunk;
            data = JSON.parse(data);
            api.deleteOssAllFile(data).then((isTrue) => {
                if (isTrue) {
                    res.status(200);
                    res.send({
                        result: {
                            'status': 'success',
                            'message': "deleted"
                        }
                    });
                } else {
                    res.status(200);
                    res.send({
                        result: {
                            'status': 'danger',
                            'message': "deleteFail"
                        }
                    });
                }
            })
        })
    });

    /**
     * 复制粘贴
     */
    router.post('/paste', (req, res) => {
        req.on("data", (chunk) => {
            let data = "";
            data += chunk;
            data = JSON.parse(data);
            const isCut = data.clipboard.type === "cut";
            const promiseArr = [];
            let toPath = data.path ? data.path + '/' : '';

            let fromOrign = "";
            let copyClient = null;
            if (data.disk == data.clipboard.disk) {
                fromOrign = "";
            } else {
                if (data.clipboard.disk == "public") {
                    fromOrign = `/${config.bucket[0]}/`;
                    copyClient = copyMap.get("internalClient");
                } else {
                    fromOrign = `/${config.bucket[1]}/`;
                    copyClient = copyMap.get("internalClientTwo");
                }
            }
            console.log("复制req.session.user", req.session.user);
            data.clipboard.directories.forEach(sourceDir => {
                let destDir = toPath + path.basename(sourceDir) + '/';
                (async () => {
                    try {
                        let message = await api.copyOssFolder(destDir, sourceDir + '/', req.session.user, fromOrign, copyClient);
                        message === 'err' ? promiseArr.push(Promise.resolve(false)) : promiseArr.push(Promise.resolve(true));
                    } catch (error) {
                        console.error(error);
                    }
                })();
            })
            data.clipboard.files.forEach(sourceDir => {
                let destDir = toPath + path.basename(sourceDir);
                promiseArr.push(internalClient.copy(destDir, fromOrign + sourceDir, {
                    headers: {
                        'x-oss-tagging': `author=${req.session.user}`,
                        // 指定如何设置目标Object的对象标签。取值为Copy或Replace。其中Copy为默认值，表示复制源Object的对象标签到目标Object。Replace表示忽略源Object的对象标签，直接采用请求中指定的对象标签。
                        'x-oss-tagging-directive': 'Replace'
                    }
                }));
            })
            Promise.all(promiseArr).then((isTrue) => {
                if (isTrue) {
                    res.status(200);
                    res.send({
                        result: {
                            status: "success",
                            message: isCut ? "cuted" : "copied"
                        }
                    });
                    if (isCut) {
                        api.getAllFilePath(data.clipboard.directories, data.clipboard.files, copyClient).then((arr) => {
                            if (arr === 'NoSuchKey') {
                                console.error('NoSuchKey');
                                return;
                            }
                            copyInternalClient = copyClient ? copyClient : internalClient;
                            arr.forEach((item) => {
                                (async () => {
                                    try {
                                        await copyInternalClient.delete(item);
                                    } catch (error) {
                                        console.error(error);
                                    }
                                })();
                            });
                        });
                    }
                } else {
                    res.status(200);
                    res.send({
                        result: {
                            status: "danger",
                            message: isCut ? "cuteFail" : "copyFail"
                        }
                    })
                }
            }).catch(e => {
                res.status(200);
                res.send({
                    result: {
                        status: "danger",
                        message: isCut ? "cuteFail" : "copyFail"
                    }
                })
            })
        });
    });
    router.post("/rename", (req, res) => {
        req.on("data", (chunk) => {
            let data = "";
            data += chunk;
            data = JSON.parse(data);
            const fileName = path.basename(data.newName);
            const reg = new RegExp('[\\\\/:*?"<>|]');
            const isValiate = reg.test(fileName);
            if (!isValiate) {
                let isFile = path.basename(data.oldName).indexOf('.') !== -1;
                if (isFile && path.basename(fileName).indexOf(".") === -1) {
                    return res.send({
                        result: {
                            status: "danger",
                            message: "renameFailExt"
                        }
                    })
                }
                let Slash = isFile ? '' : '/';
                let newName = data.oldName.split('/');
                newName.pop();
                newName = newName.join('/') + '/' + fileName;
                console.log("重命名req.session.user", req.session.user);
                if (isFile) {
                    (async () => {
                        try {
                            let info = await internalClient.copy(newName, data.oldName, {
                                headers: {
                                    'x-oss-tagging': `author=${req.session.user}`,
                                    // 指定如何设置目标Object的对象标签。取值为Copy或Replace。其中Copy为默认值，表示复制源Object的对象标签到目标Object。Replace表示忽略源Object的对象标签，直接采用请求中指定的对象标签。
                                    'x-oss-tagging-directive': 'Replace'
                                }
                            });
                            if (info.res.status === 200) {
                                let result = await internalClient.delete(data.oldName);
                                if (result.res.status === 200) {
                                    return res.send({
                                        result: {
                                            status: "success",
                                            message: "renamed"
                                        }
                                    })
                                }
                                return res.send({
                                    result: {
                                        status: "danger",
                                        mesage: "renameFail"
                                    }
                                })
                            }
                        } catch (error) {
                            return res.send({
                                result: {
                                    status: "danger",
                                    mesage: "renameFail"
                                }
                            })
                        }
                    })();
                } else {
                    try {
                        api.copyOssFolder(`${newName}${Slash}`, `${data.oldName}${Slash}`, req.session.user).then(message => {
                            if (message === 'err') {
                                return res.send({
                                    result: {
                                        status: "danger",
                                        mesage: "renameFail"
                                    }
                                })
                            }
                            api.getAllFilePath([`${data.oldName}${Slash}`], []).then((arr) => {
                                if (arr === 'NoSuchKey') {
                                    return res.send({
                                        result: {
                                            status: "danger",
                                            message: "deleteFail"
                                        }
                                    })
                                }
                                arr.forEach((item, index) => {
                                    (async () => {
                                        try {
                                            await internalClient.delete(item);
                                        } catch (error) {
                                            console.error(error);
                                        }
                                        if (arr.length - 1 == index) {
                                            res.send({
                                                result: {
                                                    status: "success",
                                                    message: "renamed"
                                                }
                                            })
                                        }
                                    })();
                                });
                            });
                        });
                    } catch (error) {
                        return res.send({
                            result: {
                                status: "danger",
                                mesage: "renameFail"
                            }
                        })
                    }
                }
            } else {
                return res.send({
                    result: {
                        status: "danger",
                        message: "IllegalCharacter"
                    }
                })
            }
        })
    });

    router.post("/upload", (req, res) => {
        let savePath = ""; //当前要存储文件的地址
        let overwrite = 0; //文件是否覆盖，0 为否,1 为覆盖
        const fromPath = []; //临时文件地址
        const fileName = []; //上传的文件名
        const form = new IncomingForm({
            multiples: true,
            encoding: 'utf-8',
            uploadDir: './tempfile',
            keepExtensions: true,
            maxFileSize: 1 * 1024 * 1024 * 1024, //512MB
            maxFields: 20, // default 1000,set 0 for unlimited
            maxFieldsSize: 20 * 1024 * 1024, //default
            hash: false, //default
        });
        form.on('error', (err) => {
            console.error(err);
            res.send({
                result: {
                    status: "danger",
                    message: "uploadError"
                }
            })
        });

        form.parse(req, (err, fields, files) => {
            function deleteFiles(fileArr) {
                fileArr.forEach(filepath => {
                    fs.unlink(filepath, function (err) {
                        if (err) {
                            console.error(err);
                        }
                    })
                })
            }
            let file = JSON.parse(JSON.stringify(files['files[]']));
            file = file instanceof Array ? file : [file];
            let ossFilePath = [];
            let renamePromiseArr = [];
            savePath = fields.path ? fields.path + '/' : '';
            overwrite = Number(fields.overwrite);
            for (let index in file) {
                fileName[index] = (file[index]).name;
                fromPath[index] = (file[index]).path;
            }
            if (err) {
                return;
            }
            if (overwrite) {
                try {
                    fileName.forEach((item, index) => {
                        renamePromiseArr.push(putStream(fromPath[index], `${savePath}${item}`, file[index].size, req.session.user));
                    })
                    Promise.all(renamePromiseArr).then(result => {
                        if (result) {
                            return res.send({
                                result: {
                                    status: "success",
                                    message: "upload"
                                }
                            })
                        }
                        return res.send({
                            result: {
                                status: "danger",
                                message: "uploadError"
                            }
                        })
                    }).catch(e => e)
                    deleteFiles(fromPath);
                } catch (error) {
                    console.error(error);
                }
            } else {
                // 不覆盖源文件
                internalClient.list({
                    prefix: savePath, //只列出符合特定前缀的文件
                    delimiter: '/'
                }).then((filesList) => {
                    if (filesList.objects[0].name === savePath) {
                        filesList.objects.shift();
                    }

                    //该目录下无文件
                    if (!filesList.objects.length) {
                        try {
                            fileName.forEach((item, index) => {
                                renamePromiseArr.push(putStream(fromPath[index], `${savePath}${item}`, file[index].size, req.session.user));
                            })
                            Promise.all(renamePromiseArr).then(result => {
                                if (result) {
                                    res.send({
                                        result: {
                                            status: "success",
                                            message: "upload"
                                        }
                                    })
                                } else {
                                    res.send({
                                        result: {
                                            status: "danger",
                                            message: "uploadError"
                                        }
                                    })
                                }
                                deleteFiles(fromPath);
                            }).catch(e => e)
                        } catch (error) {
                            console.error(error);
                        }
                    } else {
                        //该目录下有文件
                        try {
                            fileName.forEach((name, index) => {
                                let filePath = `${savePath}${name}`;
                                let suffixNum = 0,
                                    flag = false;
                                ossFilePath.push(filePath);
                                (filesList.objects || []).forEach((item) => {
                                    if (item.name.lastIndexOf('/') === item.name.length - 1) return;
                                    let suffix = path.basename(item.name, path.extname(name));
                                    //文件名和扩展名都相同
                                    if (name.replace(/\.(?<=\.).*/g, "") === suffix.replace(/\(.*\)/, "") && path.extname(name) === path.extname(path.basename(item.name))) {
                                        if (!suffix.match(/\(.*\)/)) { //is null
                                            // suffixNum = 0;
                                            flag = true;
                                            return;
                                        }
                                        let numMatch = suffix.match(/\(.*\)/)[0].match(/\d+/);
                                        let num = suffix.match(/\(.*\)/) ? Number(numMatch ? numMatch[0] : 0) : 0;
                                        suffixNum = num > suffixNum ? num : suffixNum; //文件括号中的数值
                                        flag = true;
                                    }
                                })
                                let suffixName = !flag ? name : name.replace(/(.*)(?=\.)/, `$1(${suffixNum+1})`);
                                renamePromiseArr.push(putStream(fromPath[index], `${savePath}${suffixName}`, file[index].size, req.session.user));
                            });
                        } catch (error) {
                            console.error(error);
                        }
                        Promise.all(renamePromiseArr).then(() => {
                            res.send({
                                result: {
                                    status: "success",
                                    message: "upload"
                                }
                            })
                            deleteFiles(fromPath);
                        }).catch(e => {
                            console.error("renameError:", e);
                            res.send({
                                result: {
                                    status: "danger",
                                    message: "uploadError"
                                }
                            });
                            deleteFiles(fromPath);
                        })
                    }
                }).catch(e => {
                    res.send({
                        result: {
                            status: "danger",
                            message: "uploadPathError"
                        }
                    });
                    deleteFiles(fromPath);
                });
            }



            async function putStream(localfile, ossfile, size, author = "") {
                try {
                    let stream = fs.createReadStream(localfile);
                    let result = await internalClient.putStream(
                        ossfile, stream, {
                            contentLength: size,
                            headers: {
                                'x-oss-tagging': `author=${author}`,
                            }
                        });
                    // await internalClient.putObjectTagging(ossfile, {
                    //     author: author
                    // });
                    if (result.res.status === 200) {
                        return true;
                    }
                } catch (err) {
                    return false;
                }
            }
        });
    })

    return router;
};

