const express = require("express");
const bodyParser = require("body-parser");
const session = require("express-session");
let CONFIG = require("./app/config/server.config.js");
const passport = require("passport");

module.exports.parsers = function(app) {
  app.use(bodyParser.json());
};

module.exports.loadModels = function() {
  require("./app/db/mongoose.connect")();
  require("./app/db/models/user.model");
  require("./app/db/models/posts.model");
};

module.exports.passport = function(app) {
  require("./app/authentication/passport");
  app.use(passport.initialize());
  app.use(passport.session());
};
module.exports.session = function(app) {
  app.use(
    session({
      resave: false,
      saveUninitialized: false,
      secret:
        process.env.SESSION_SECRET || "<KEY>"
    })
  );
};
module.exports.routes = function(app) {
  let router = express.Router();
  app.get("/", (req, res) => res.send("Welcome!!"));
  require("./app/routes/user.routes")(router);
  require("./app/routes/posts.routes")(router);
  app.use(router);
};

module.exports.init = function() {
  let app = express();
  this.parsers(app);
  this.loadModels();
  this.session(app);
  this.passport(app);
  this.routes(app);
  app.set("port", process.env.PORT || 3000);
  return app;
};

