const crypto = require('crypto');

const ALGORITHM = 'aes-256-gcm';

const deriveKey = (key) => {
    return crypto.scryptSync(String(key), 'fixed-salt-for-scrypt', 32);
};

const encrypt = (str, key="aes256-key@123") => {
    if (!str || !key) return null;
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(ALGORITHM, deriveKey(key), iv);
    const encrypted = Buffer.concat([cipher.update(String(str), 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return Buffer.concat([iv, tag, encrypted]).toString('base64');
}

const decrypt = (str, key="aes256-key@123") => {
    if (!str || !key) return null;
    const data = Buffer.from(String(str), 'base64');
    const iv = data.subarray(0, 16);
    const tag = data.subarray(16, 32);
    const cipherText = data.subarray(32);
    const decipher = crypto.createDecipheriv(ALGORITHM, deriveKey(key), iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(cipherText), decipher.final()]).toString('utf8');

