const {languages} = (function()
{
  let l = require("google-translate-api").languages;
  return {
    languages: Object.entries(l).filter(([k, v]) => typeof v == "string" && k != "auto"),
    getLangCode: l.getCode
  };
})();

const parser = new ArgumentParser({
