/*Specify inputs to create these on the fly
div_id: specifies the dom div to attach inputs and renders to
sso: the ss or dss object which you are connecting this input set to
ctdt: 
*/

//MUST ADD DESCRIPTOR CHECKER ON TYPE!!!
function ssmi(div_id,sso,spec_iso=false, ctdt = "CT",type='ss'){
    if (ctdt=="DT" && type=="dss"){
        console.log("cannot have discrete time system with E matrix!");
        return false;
    }
    var sso = sso;
    this.element = document.getElementById(div_id);
    this.element.className += "eq_input_area";
    var inputs="";
    console.log(sso);
    var ssmio = this;

    inputs +=""
    inputs+= `<div class="gen_input">\\(\\textbf{A}\\): <input type="text" size="50" value="[[1,0,2],[5,4,2],[0,0,1]]" name="A_${div_id}" id="A_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>
    <div class="gen_input">\\(\\textbf{B}\\): <input type="text" size="50" value="[1,2,3]" name="B_${div_id}" id="B_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>
    <div class="gen_input">\\(\\textbf{C}\\): <input type="text" size="50" value="[1,2,3]" name="C_${div_id}" id="C_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>
    <div class="gen_input">\\(\\textbf{D}\\): <input type="text" size="50" value="[0]" name="D_${div_id}" id="D_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>`;
    if (sso.type=='dss')inputs += `<div class="gen_input">\\(\\textbf{E}\\): <input type="text" size="50" value="[[1,0,0],[0,1,0],[0,0,1]]" name="E_${div_id}" id="E_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>`;


    if (spec_iso){
        inputs += `<div class="gen_input">\\(\\textbf{x}\\): <input type="text" size="50" value="[x_1,x_2,x_3]" name="x_${div_id}" id="x_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>
        <div class="gen_input">\\(\\textbf{y}\\): <input type="text" size="50" value="[\\theta]" name="y_${div_id}" id="y_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>
        <div class="gen_input">\\(\\textbf{u}\\): <input type="text" size="50" value="[v_i]" name="u_${div_id}" id="u_${div_id}" class="matrix_input_${div_id}" maxlength="100" /><br></div>
        `;
    }
    inputs+=`<button type="button" class="update_button" id="update_${div_id}">Check & Update</button>`;
    inputs+=`<div class="error_zone" id="error_text_${div_id}"></div>`;
    inputs+="";

    var displays = `<div id="displayed_eq1_${div_id}" class="matrix_to_render"></div><div id="displayed_eq2_${div_id}"class="matrix_to_render">`;

    this.element.innerHTML = inputs+displays;


    var grab_input = function(input_obj){
        var matrix = input_obj.id[0];
        vals = input_obj.value;
        vals = vals.replace(' ', '');
        if (matrix ==="x" || matrix==="y" || matrix==="u"){
            vals = vals.replace('[','').replace(']','').split(',');
            var tempm = [];
            for(var i =0; i<vals.length;i++){
                tempm.push(vals[i]);
            }
            sso.update(matrix,tempm);
            return [true,""];
        }else{
            try{
                mat = eval(vals);
                console.log("new mtarix");
                sso.update(matrix,mat);
                return [true,""];

            }catch(err){
                console.log("not a full matrix");
                console.log(mat);
                console.log(vals);
                console.log(err);
                sso.update(matrix,[]);
                return [false,`${matrix} matrix input has syntax error`]
            }
        }
    }


    ssmio.ourinputs = document.getElementsByClassName(`matrix_input_${div_id}`);

    var process_all_inputs = function(){
        var errors = [];
        for (var i=0; i<ssmio.ourinputs.length;i++){
            var out = grab_input(ssmio.ourinputs[i]);
            if (out[0]==false) errors.push(out[1]);
        }
        var mat_check = sso.check_matrix_sizes();
        if (errors!==[] || !mat_check[0]){
            var error_log = "<ul>";
            for (var i = 0; i<errors.length;i++){
                error_log += "<li>";
                error_log += errors[i];
                error_log +="</li>";
            }
            if (!mat_check[0]){
                error_log += "<li>";
                error_log += mat_check[1];
                error_log +="</li>";
            }
            error_log +="</ul>";
            document.getElementById(`error_text_${div_id}`).innerHTML=error_log;
        }else{
            document.getElementById(`error_text_${div_id}`).innerHTML=null;
        }
        var top = "$$";
        if(type==='dss') top +=render_matrix(sso.E,sso.E.length,sso.E[0].length);
        top+=render_matrix(sso.x_repn,"x");
        if(ctdt==="CT") top += "\\cdot\\frac{d}{dt}";
        top += "=";
        top+=render_matrix(sso.A,"A");
        top+=render_matrix(sso.x_rep,"x");
        top += "+";
        top+=render_matrix(sso.B,"B");
        top+=render_matrix(sso.u_rep,"u");
        top +="$$";
        var bottom = "$$";
        bottom += render_matrix(sso.y_rep,"y");
        bottom += "=";
