            return [false, `Specified symbolic u length incorrect! Must agree with A, B, and C matrices! Should be ${ssobj.u.length} long`];
        }
        //all good.!!
        return [true,""];

    }

    //initialization
    this.check_matrix_sizes();
    this.build_numerical_iso();
    this.standardize_sym_iso();

