        } else {
            alert('이메일 형식을 확인해주세요!');
        }
    };

    return (
        <>
            <button onClick={() => {
                openPasswordModal();
                // console.log(showModal)
            }}>
                비밀번호 찾기
            </button>
            {showModal ? (
                <div>
                    <p>비밀번호를 잃어버리셨나요?
                        devU에 가입한 이메일을 정확히 입력해 주세요.
                        이메일을 통해 비밀번호 수정 링크가 전송됩니다.</p>
                    <input
                        id="email"
                        name="email"
                        value={email}
                        onChange={(e) => onChangeEmail(e)}
                        placeholder="이메일"
                    />
                    <button onClick={() => { passwordUrlEmail(); }}>비밀번호 찾기</button>

                </div>
            )
                : null
            }
        </>
    );
