                    this.pointBaseOffsets[i * 8 + 2] = 0.5;
                    this.pointBaseOffsets[i * 8 + 3] = -0.5;
                    this.pointBaseOffsets[i * 8 + 4] = -0.5;
                    this.pointBaseOffsets[i * 8 + 5] = 0.5;
                    this.pointBaseOffsets[i * 8 + 6] = 0.5;
                    this.pointBaseOffsets[i * 8 + 7] = 0.5;

                    var size = 70 / 2;
