                    }

                    if (EterationArray[i].OutPut1 == "2" && EterationArray[i].TestPass_ID == testPassId) {
                        itArray2.push(EterationArray[i]);
                    }

                    if (EterationArray[i].OutPut1 == "3" && EterationArray[i].TestPass_ID == testPassId) {
                        itArray3.push(EterationArray[i]);
